assert devices(discover_audio())['clear']
report=REVIEW/'reports/stage5_02_board'/'implementation_build';report.mkdir()
accepted=REVIEW/'build/stage5_01_board/asr_llm_tts_smoke'
accepted_hash=hashlib.sha256(accepted.read_bytes()).hexdigest()
base=REVIEW/'reports/stage5_02_board/baseline_build_source'
shutil.copytree(REVIEW/'reports/stage5_02_board/baseline_and_npu_probe/baseline_5_1_source',base)
def install(destination,rows,backup):
    for row in rows:
        p=destination/row['file'];assert p.resolve().is_relative_to(destination.resolve()) and not p.is_symlink()
        if p.exists():
            current=hashlib.sha256(p.read_bytes()).hexdigest()
            assert current in {row['before'],row['sha256']},'unexpected prior content: '+row['file']
        else:assert row['before'] is None,'required baseline file absent'
    for row in rows:
        p=destination/row['file'];data=base64.b64decode(row['data']);assert hashlib.sha256(data).hexdigest()==row['sha256']
        if p.exists():
            saved=backup/row['file'];saved.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(p,saved)
        p.parent.mkdir(parents=True,exist_ok=True)
        temp=p.with_name(p.name+'.stage5_02_tmp')
        with temp.open('xb') as f:f.write(data)
        os.replace(temp,p)
install(base,BASELINE,report/'baseline_before_instrumentation')
install(REVIEW,CANDIDATE,report/'candidate_before')
for label,rows in [('candidate',CANDIDATE),('baseline',BASELINE)]:
    (report/(label+'_source_manifest.json')).write_text(json.dumps([{k:v for k,v in row.items() if k!='data'} for row in rows],indent=2)+'\n')
results=[]
def step(label,cmd,limit):
    (report/(label+'.command.json')).write_text(json.dumps(cmd,indent=2)+'\n')
    with (report/(label+'.stdout.log')).open('wb') as out,(report/(label+'.stderr.log')).open('wb') as err,(report/(label+'.disk.jsonl')).open('w') as samples:
        process=subprocess.Popen(cmd,stdout=out,stderr=err,start_new_session=True);started=time.monotonic();reason=None
        while process.poll() is None:
            free=shutil.disk_usage(REVIEW).free;samples.write(json.dumps({'time':time.time(),'free_bytes':free})+'\n');samples.flush()
            if free<500*1024**2 or time.monotonic()-started>limit:
                reason='disk_below_500MiB' if free<500*1024**2 else 'timeout'
                os.killpg(process.pid,signal.SIGTERM)
                try:process.wait(timeout=15)
                except subprocess.TimeoutExpired:os.killpg(process.pid,signal.SIGKILL);process.wait(timeout=10)
                break
            time.sleep(1)
        code=process.wait()
    result={'step':label,'returncode':code,'reason':reason,'seconds':time.monotonic()-started};results.append(result)
    (report/(label+'.result.json')).write_text(json.dumps(result,indent=2)+'\n')
    print('BUILD_STEP',json.dumps(result),flush=True)
    print((report/(label+'.stdout.log')).read_text(errors='replace'),flush=True)
    print((report/(label+'.stderr.log')).read_text(errors='replace'),flush=True)
    return code==0 and reason is None
ok=True
for variant,source in [('baseline',base),('candidate',REVIEW)]:
    build=REVIEW/('build/stage5_02_baseline' if variant=='baseline' else 'build/stage5_02_board')
    assert not build.exists(),'new build directory already exists'
    config='source "$1/tools/stage5_board_paths.sh"; exec timeout --signal=TERM --kill-after=15s 180s cmake -S "$2" -B "$3" -DCMAKE_BUILD_TYPE=Release -DBUILD_TESTING=ON -DBUILD_WITH_RKLLM=ON -DBUILD_WITH_VLM=ON -DENABLE_SHERPA_ASR=ON -DSHERPA_ONNX_ROOT="$STAGE5_SHERPA" -DRKLLM_SDK_ROOT="$STAGE5_RKLLM" -DRKNN_INCLUDE_DIR="$STAGE5_RKNN_INCLUDE" -DRKNN_RUNTIME_LIBRARY="$STAGE5_RKNN_LIBRARY"'
    for label,cmd,limit in [(variant+'_configure',['bash','-c',config,'stage5_02',str(REVIEW),str(source),str(build)],200),(variant+'_build',['timeout','--signal=TERM','--kill-after=15s','600s','cmake','--build',str(build),'--parallel','3'],620),(variant+'_ctest',['bash','-c','source "$1/tools/stage5_board_paths.sh"; exec timeout --signal=TERM --kill-after=10s 120s ctest --test-dir "$2" --output-on-failure --timeout 30 --output-junit "$3"','stage5_02',str(REVIEW),str(build),str(report/(variant+'_ctest.xml'))],140)]:
        if not step(label,cmd,limit):ok=False;break
    if not ok:break
post={'steps':results,'original_321_unchanged':fingerprint()==EXPECTED,'accepted_stage5_01_binary_unchanged':hashlib.sha256(accepted.read_bytes()).hexdigest()==accepted_hash,'disk_free_bytes':shutil.disk_usage(REVIEW).free,'successful':ok}
(report/'result.json').write_text(json.dumps(post,indent=2)+'\n');print('BUILD_FINAL',json.dumps(post),flush=True)
raise SystemExit(0 if ok and post['original_321_unchanged'] and post['accepted_stage5_01_binary_unchanged'] else 1)
